4	namespace Gatekeeper.Web.Data;
5	
6	public class GatekeeperDbContext(DbContextOptions<GatekeeperDbContext> options)
7	    : IdentityDbContext<ApplicationUser>(options)
8	{
9	    public DbSet<Customer> Customers => Set<Customer>();
10	
11	    // 'new' because IdentityDbContext already exposes Roles/UserRoles for its own
12	    // IdentityRole tables. Gatekeeper's access-control roles are a separate concept.
13	    public new DbSet<Role> Roles => Set<Role>();
14	    public new DbSet<UserRole> UserRoles => Set<UserRole>();
15	
16	    public DbSet<Grant> Grants => Set<Grant>();
17	    public DbSet<AuditLogEntry> AuditLog => Set<AuditLogEntry>();
18	
19	    protected override void OnModelCreating(ModelBuilder builder)
20	    {
21	        base.OnModelCreating(builder);
22	
23	        // Store enums as readable text in the database rather than ints.
24	        builder.Entity<Customer>(e =>
25	        {
26	            e.Property(c => c.Name).HasMaxLength(200).IsRequired();
27	            e.Property(c => c.PlanTier).HasConversion<string>().HasMaxLength(20);
28	            e.HasIndex(c => c.Name).IsUnique();
29	        });
30	
31	        builder.Entity<ApplicationUser>(e =>
32	        {
33	            e.Property(u => u.DisplayName).HasMaxLength(200);
34	            e.HasOne(u => u.Customer)
35	                .WithMany(c => c.Users)
36	                .HasForeignKey(u => u.CustomerId)
37	                .OnDelete(DeleteBehavior.SetNull);
38	        });
39	
40	        builder.Entity<Role>(e =>
41	        {
42	            e.Property(r => r.Name).HasMaxLength(200).IsRequired();
43	            e.Property(r => r.Description).HasMaxLength(1000);
44	
45	            e.HasOne(r => r.Customer)
46	                .WithMany(c => c.Roles)
47	                .HasForeignKey(r => r.CustomerId)
48	                .OnDelete(DeleteBehavior.Cascade);
49	
50	            e.HasOne(r => r.Parent)
51	                .WithMany(r => r.Children)
52	                .HasForeignKey(r => r.ParentRoleId)
53	                .OnDelete(DeleteBehavior.Restrict);
54	
55	            e.HasIndex(r => new { r.CustomerId, r.Name }).IsUnique();
56	        });
57	
58	        builder.Entity<UserRole>(e =>
59	        {
60	            e.HasOne(ur => ur.User)
61	                .WithMany(u => u.UserRoles)
62	                .HasForeignKey(ur => ur.UserId)
63	                .OnDelete(DeleteBehavior.Cascade);
64	
65	            e.HasOne(ur => ur.Role)
66	                .WithMany(r => r.UserRoles)
67	                .HasForeignKey(ur => ur.RoleId)
68	                .OnDelete(DeleteBehavior.Cascade);
69	
70	            e.HasIndex(ur => new { ur.UserId, ur.RoleId }).IsUnique();
71	        });
72	
73	        builder.Entity<Grant>(e =>
74	        {
75	            e.Property(g => g.Effect).HasConversion<string>().HasMaxLength(10);
76	            e.Property(g => g.Permission).HasMaxLength(200).IsRequired();
77	            e.Property(g => g.Resource).HasMaxLength(200).IsRequired();
78	
79	            e.HasOne(g => g.Customer)
80	                .WithMany(c => c.Grants)
81	                .HasForeignKey(g => g.CustomerId)
82	                .OnDelete(DeleteBehavior.Cascade);
83	
84	            e.HasOne(g => g.User)
85	                .WithMany(u => u.Grants)
86	                .HasForeignKey(g => g.UserId)
87	                .OnDelete(DeleteBehavior.Cascade);
88	
89	            e.HasOne(g => g.Role)
90	                .WithMany(r => r.Grants)
91	                .HasForeignKey(g => g.RoleId)
92	                .OnDelete(DeleteBehavior.Cascade);
93	
94	            // A grant must hang off exactly one subject: a user XOR a role.
95	            e.ToTable(t => t.HasCheckConstraint(
96	                "CK_Grant_OneSubject",
97	                "(\"UserId\" IS NOT NULL AND \"RoleId\" IS NULL) OR (\"UserId\" IS NULL AND \"RoleId\" IS NOT NULL)"));
98	
99	            e.HasIndex(g => new { g.CustomerId, g.Permission, g.Resource });
100	        });
101	
102	        builder.Entity<AuditLogEntry>(e =>
103	        {
104	            e.Property(a => a.ActorName).HasMaxLength(256).IsRequired();
105	            e.Property(a => a.Action).HasMaxLength(50).IsRequired();
106	            e.Property(a => a.EntityType).HasMaxLength(100).IsRequired();
107	            e.Property(a => a.EntityId).HasMaxLength(256).IsRequired();
108	            e.Property(a => a.Summary).HasMaxLength(2000).IsRequired();
109	            e.HasIndex(a => a.Timestamp);
110	        });
111	    }
112	}
